def ecl_to_eq(lam):
    eps = 23.4393 * D2R
    l = lam * D2R
    ra = math.atan2(math.sin(l) * math.cos(eps), math.cos(l))
    de = math.asin(math.sin(eps) * math.sin(l))
    return (ra / D2R) % 360, de / D2R


def star_ink(bv, m):
    t = max(-0.3, min(1.8, bv))
    f = max(0.0, min(1.0, (m - 4.2) / 2.2)) * 0.72
    if t < 0.4:
        tint, w = (24, 34, 92), min(1.0, (0.4 - t) / 0.5)
    elif t > 1.1:
        tint, w = (88, 52, 18), min(1.0, (t - 1.1) / 0.5)
    else:
        tint, w = (26, 26, 26), 0.0
    c = [22 + (x - 22) * w * 0.8 for x in tint]
    return "#%02x%02x%02x" % tuple(int(round(a + (190 - a) * f)) for a in c)


