def paint_om01():
    a0, d0, s, th, ox, oy = 87.9146 * D2R, 61.8886 * D2R, 370.835, 0.0274 * D2R, 499.18, 418.80
    W, H = 1173, 840
    out = []
    for ra, de, m, bv in reversed(STARS):
        a, d = ra * D2R, de * D2R
        cosc = math.sin(d0) * math.sin(d) + math.cos(d0) * math.cos(d) * math.cos(a - a0)
        if cosc < 0:
            continue
        k = 2 / (1 + cosc)
        X = -math.cos(d) * math.sin(a - a0) * k
        Y = (math.cos(d0) * math.sin(d) - math.sin(d0) * math.cos(d) * math.cos(a - a0)) * k
        u = ox + s * (X * math.cos(th) - Y * math.sin(th))
        v = oy - s * (X * math.sin(th) + Y * math.cos(th))
        if -8 < u < W + 8 and -8 < v < H + 8:
            out.append(("dot", u, v, max(0.75, 0.75 + 0.78 * (6.3 - m)), star_ink(bv, m)))
    out.append(("rect", 1, 1, W - 1, H - 1, "#222", 1.5))
    return out


TM = {"a0": 14.19235 * 15 * D2R, "xe": 301.68, "y0": 312.92, "R": 132.592}
TM["P"] = 2 * math.pi * TM["R"]


def tm(ra, de):
    a, d = ra * D2R, de * D2R
    lat = math.atan2(math.tan(d), math.cos(a - TM["a0"]))
    B = max(-0.99995, min(0.99995, math.cos(d) * math.sin(a - TM["a0"])))
    return TM["xe"] + TM["R"] * lat, TM["y0"] - TM["R"] * math.atanh(B)


def unwrap(pts):
    out, prev = [], None
    for u, v in pts:
        if prev is not None:
            while u - prev > TM["P"] / 2:
                u -= TM["P"]
            while prev - u > TM["P"] / 2:
                u += TM["P"]
        out.append((u, v))
        prev = u
    return out


def tm_lines(raw, col, w, dash=None):
    pts = unwrap(raw)
    out = []
    for k in (-1, 0, 1):
        seg = []
        for u, v in pts:
            if abs(v) > 4000:
                if len(seg) > 1:
                    out.append(("line", seg, col, w, dash))
                seg = []
                continue
            seg.append((u + k * TM["P"], v))
        if len(seg) > 1:
            out.append(("line", seg, col, w, dash))
    return out


def tm_poly(ring, fill, outline):
    dense = []
    for i in range(len(ring)):
        p, q = ring[i], ring[(i + 1) % len(ring)]
        dr = (q[0] - p[0] + 540) % 360 - 180
        n = max(1, int(math.ceil(max(abs(dr), abs(q[1] - p[1])) / 0.5)))
        for j in range(n):
            dense.append(tm(p[0] + dr * j / n, p[1] + (q[1] - p[1]) * j / n))
    pts = unwrap(dense)
    return [("poly", [(u + k * TM["P"], v) for u, v in pts], fill, outline) for k in (-1, 0, 1)]


def paint_om02():
    W, H = 833, 625
    out = []
    for de in range(-80, 81, 10):
        out += tm_lines([tm(ra / 2, de) for ra in range(0, 721)], "#bdbdbd", 0.8)
    for ra in range(0, 360, 15):
        out += tm_lines([tm(ra, de / 4) for de in range(-358, 359)], "#bdbdbd", 0.8)
    for c in ("Sgr", "Cyg", "UMa", "Ori"):
        for ring in BOUNDS[c]:
            out += tm_poly(ring, "#e2ebe2", "#2b2b2b")
    for ring in BOUNDS["Vir"]:
        out += tm_poly(ring, "#cdcdcd", "#2b2b2b")
    for ring in BOUNDS["Crv"]:
        out += tm_poly(ring, "#a2a2a2", "#2b2b2b")
    for c in ("Vir", "Crv"):
        for line in CLINES[c]:
            p = []
            for i in range(len(line) - 1):
                a, b = line[i], line[i + 1]
                dr = (b[0] - a[0] + 540) % 360 - 180
                for j in range(8):
                    p.append(tm(a[0] + dr * j / 8, a[1] + (b[1] - a[1]) * j / 8))
            p.append(tm(*line[-1]))
            out += tm_lines(p, "#c035c0", 1.1)
    for lab, x, y in (("C1", 310, 285), ("C2", 265, 361)):
        out.append(("box", x - 8, y - 6, x + 8, y + 5, "#fff", "#333"))
        out.append(("text", x, y, lab, "#111", 7))
    out += tm_lines([tm(*ecl_to_eq(l / 2)) for l in range(0, 721)], "#2632c8", 1.2, (6, 5))
    for x, y in ((540, 77), (782, 73), (48, 490)):
        out.append(("rect", x - 17, y - 17, x + 17, y + 17, "#d33a5c", 1.6))
    for x, y in ((469, 41), (280, 512), (756, 540)):
        out.append(("oval", x - 18, y - 18, x + 18, y + 18, "#2525b8", 1.6))
    out.append(("rect", 1, 1, W - 1, H - 1, "#222", 1.5))
    return out


def mer_y(a):
    return 391 - 364.4 * math.log(math.tan((45 + a / 2) * D2R))


def paint_om03a():
    W, H, px, x90 = 760, 423, 6.364, 380
    out = []
    a = 5
    while mer_y(a) > 0:
        out.append(("line", [(0, mer_y(a)), (W, mer_y(a))], "#555", 0.9, None))
        a += 5
    x = x90 % (5 * px)
    while x < W:
        out.append(("line", [(x, 0), (x, 391)], "#555", 0.9, None))
        x += 5 * px
    out.append(("box", 0, 391, W, H, "#666", "#666"))
    for a in range(10, 51, 10):
        out.append(("box", 2, mer_y(a) - 8, 32, mer_y(a) + 8, "#fff", "#fff"))
        out.append(("text", 16, mer_y(a), "%d°" % a, "#222", 10))
    out.append(("line", [(x90, 385), (x90, 391)], "#111", 1.5, None))
    out.append(("text", x90 + 12, 379, "P", "#111", 12))
    out.append(("rect", 1, 1, W - 1, H - 1, "#222", 1.5))
    return out


